-- Canonical communications contract: match production calls/messages schema.
CREATE OR REPLACE FUNCTION public.capability_dispatch(p_capability text, p_input jsonb DEFAULT '{}'::jsonb)\\n RETURNS jsonb\\n LANGUAGE plpgsql\\n SET search_path TO 'public'\\nAS $function$\\ndeclare\\n  v_user_id uuid := auth.uid();\\n  v_limit int := least(100, greatest(1, coalesce((p_input->>'limit')::int, 20)));\\n  v_id uuid;\\n  v_conversation uuid;\\n  v_cursor timestamptz;\\nbegin\\n  p_capability := btrim(coalesce(p_capability,''));\\n  if p_capability not in ('testagram.capabilities.list','testagram.health.read') and v_user_id is null then\\n    raise exception using errcode='28000', message='Authentication required';\\n  end if;\\n\\n  case p_capability\\n    when 'testagram.conversations.list' then\\n      return jsonb_build_object(\\n        'items', coalesce((\\n          select jsonb_agg(x.obj order by x.updated_at desc)\\n          from (\\n            select c.updated_at,\\n              jsonb_build_object(\\n                'id', c.id,\\n                'created_at', c.created_at,\\n                'updated_at', c.updated_at,\\n                'kind', c.kind,\\n                'title', c.title,\\n                'members', coalesce((\\n                  select jsonb_agg(jsonb_build_object(\\n                    'id', p.id, 'username', p.username, 'display_name', p.display_name,\\n                    'avatar_url', p.avatar_url,\\n                    'verified', (p.verified_tier is not null and p.verified_tier <> 'none')\\n                  ) order by p.username)\\n                  from public.conversation_members cm\\n                  join public.profiles p on p.id = cm.user_id\\n                  where cm.conversation_id = c.id and cm.left_at is null\\n                ), '[]'::jsonb),\\n                'unread_count', coalesce((\\n                  select count(*)\\n                  from public.messages m\\n                  join public.conversation_members me\\n                    on me.conversation_id = m.conversation_id\\n                   and me.user_id = v_user_id\\n                   and me.left_at is null\\n                  where m.conversation_id = c.id\\n                    and m.sender_id <> v_user_id\\n                    and m.created_at > coalesce(me.last_read_at, 'epoch'::timestamptz)\\n                    and m.deleted_at is null\\n                ), 0),\\n                'latest_message', (\\n                  select jsonb_build_object(\\n                    'id', lm.id, 'conversation_id', lm.conversation_id, 'sender_id', lm.sender_id,\\n                    'created_at', lm.created_at, 'deleted_at', lm.deleted_at,\\n                    'ciphertext', lm.ciphertext, 'nonce', lm.nonce, 'key_epoch', lm.key_epoch,\\n                    'message_type', lm.message_type, 'attachment_metadata', lm.attachment_metadata\\n                  )\\n                  from public.messages lm\\n                  where lm.conversation_id = c.id and lm.deleted_at is null\\n                  order by lm.created_at desc limit 1\\n                )\\n              ) obj\\n            from public.conversations c\\n            where exists (\\n              select 1 from public.conversation_members cm\\n              where cm.conversation_id = c.id and cm.user_id = v_user_id and cm.left_at is null\\n            )\\n            order by c.updated_at desc\\n            limit v_limit\\n          ) x\\n        ), '[]'::jsonb),\\n        'next_cursor', null\\n      );\\n\\n    when 'testagram.conversations.create' then\\n      if jsonb_typeof(p_input->'member_ids') <> 'array'\\n         or jsonb_array_length(p_input->'member_ids') < 1 then\\n        raise exception using errcode='22023', message='At least one member is required';\\n      end if;\\n\\n      if jsonb_array_length(p_input->'member_ids') = 1 then\\n        select c.id into v_conversation\\n        from public.conversations c\\n        where c.kind = 'direct'\\n          and exists (\\n            select 1 from public.conversation_members cm\\n            where cm.conversation_id = c.id and cm.user_id = v_user_id and cm.left_at is null\\n          )\\n          and (select count(*) from public.conversation_members cm2\\n               where cm2.conversation_id = c.id and cm2.left_at is null) = 2\\n          and exists (\\n            select 1 from public.conversation_members cm3\\n            where cm3.conversation_id = c.id\\n              and cm3.user_id = (p_input->'member_ids'->>0)::uuid\\n              and cm3.left_at is null\\n          )\\n        order by c.updated_at desc\\n        limit 1;\\n      end if;\\n\\n      if v_conversation is null then\\n        insert into public.conversations(created_by, kind, title, encrypted, participant_1, participant_2)\\n        values (\\n          v_user_id,\\n          case when jsonb_array_length(p_input->'member_ids') > 1 then 'group' else 'direct' end,\\n          nullif(p_input->>'title',''),\\n          true,\\n          case when jsonb_array_length(p_input->'member_ids') = 1 then v_user_id end,\\n          case when jsonb_array_length(p_input->'member_ids') = 1 then (p_input->'member_ids'->>0)::uuid end\\n        )\\n        returning id into v_conversation;\\n\\n        insert into public.conversation_members(conversation_id,user_id,role)\\n        values(v_conversation,v_user_id,'owner');\\n\\n        insert into public.conversation_members(conversation_id,user_id,role)\\n        select v_conversation,x::uuid,'member'\\n        from jsonb_array_elements_text(p_input->'member_ids') x\\n        where x::uuid <> v_user_id\\n        on conflict do nothing;\\n      end if;\\n\\n      return jsonb_build_object('conversation_id',v_conversation);\\n\\n    when 'testagram.messages.list' then\\n      if not exists (\\n        select 1 from public.conversation_members cm\\n        where cm.conversation_id = (p_input->>'conversation_id')::uuid\\n          and cm.user_id = v_user_id and cm.left_at is null\\n      ) then\\n        raise exception using errcode='42501', message='Conversation membership required';\\n      end if;\\n\\n      v_cursor := nullif(p_input->>'cursor','')::timestamptz;\\n\\n      return jsonb_build_object(\\n        'items', coalesce((\\n          select jsonb_agg(to_jsonb(x) order by x.created_at asc)\\n          from (\\n            select\\n              m.id, m.conversation_id, m.sender_id,\\n              coalesce(m.plaintext_content,'') as body,\\n              null::text as media_url,\\n              null::text as media_type,\\n              m.created_at, m.edited_at, m.deleted_at,\\n              m.reply_to_id as reply_to_message_id,\\n              null::uuid as shared_post_id,\\n              m.client_message_id,\\n              null::timestamptz as delivered_at,\\n              case when m.sender_id = v_user_id then null else m.created_at end as read_at,\\n              (m.ciphertext is not null and m.nonce is not null) as e2ee_enabled,\\n              'v1'::text as e2ee_version,\\n              m.key_epoch as e2ee_epoch,\\n              m.ciphertext, m.nonce,\\n              null::text as aad,\\n              jsonb_build_object(\\n                'id',p.id,'username',p.username,'display_name',p.display_name,\\n                'avatar_url',p.avatar_url,\\n                'verified',(p.verified_tier is not null and p.verified_tier <> 'none')\\n              ) as sender,\\n              m.attachment_metadata\\n            from public.messages m\\n            left join public.profiles p on p.id = m.sender_id\\n            where m.conversation_id = (p_input->>'conversation_id')::uuid\\n              and (v_cursor is null or m.created_at < v_cursor)\\n            order by m.created_at desc\\n            limit v_limit\\n          ) x\\n        ), '[]'::jsonb),\\n        'next_cursor', (\\n          select min(x.created_at)::text\\n          from (\\n            select m.created_at\\n            from public.messages m\\n            where m.conversation_id = (p_input->>'conversation_id')::uuid\\n              and (v_cursor is null or m.created_at < v_cursor)\\n            order by m.created_at desc\\n            limit v_limit\\n          ) x\\n        )\\n      );\\n\\n    when 'testagram.messages.send_encrypted' then\\n      if not exists (\\n        select 1 from public.conversation_members cm\\n        where cm.conversation_id = (p_input->>'conversation_id')::uuid\\n          and cm.user_id = v_user_id and cm.left_at is null\\n      ) then\\n        raise exception using errcode='42501', message='Conversation membership required';\\n      end if;\\n\\n      insert into public.messages(\\n        conversation_id, sender_id, client_message_id, ciphertext, nonce,\\n        key_epoch, message_type, reply_to_id, attachment_metadata\\n      )\\n      values(\\n        (p_input->>'conversation_id')::uuid,\\n        v_user_id,\\n        nullif(p_input->>'client_message_id',''),\\n        p_input->>'ciphertext',\\n        p_input->>'nonce',\\n        coalesce((p_input->>'e2ee_epoch')::bigint,1),\\n        'text',\\n        nullif(p_input->>'reply_to_message_id','')::uuid,\\n        '[]'::jsonb\\n      )\\n      on conflict(sender_id,client_message_id) where client_message_id is not null\\n      do nothing\\n      returning id into v_id;\\n\\n      if v_id is null then\\n        select id into v_id from public.messages\\n        where sender_id=v_user_id\\n          and client_message_id=nullif(p_input->>'client_message_id','')\\n        limit 1;\\n      end if;\\n\\n      if v_id is null then raise exception 'MESSAGE_NOT_CREATED'; end if;\\n\\n      return jsonb_build_object('message_id',v_id,'encrypted',true);\\n\\n    when 'testagram.messages.edit_encrypted' then\\n      update public.messages\\n      set ciphertext=p_input->>'ciphertext',\\n          nonce=p_input->>'nonce',\\n          key_epoch=coalesce((p_input->>'e2ee_epoch')::bigint,key_epoch),\\n          edited_at=now(),\\n          updated_at=now()\\n      where id=(p_input->>'message_id')::uuid\\n        and sender_id=v_user_id\\n        and deleted_at is null;\\n      if not found then raise exception 'MESSAGE_NOT_FOUND'; end if;\\n      return jsonb_build_object('message_id',(p_input->>'message_id')::uuid,'edited',true);\\n\\n    when 'testagram.messages.delete' then\\n      update public.messages\\n      set deleted_at=now(), updated_at=now()\\n      where id=(p_input->>'message_id')::uuid\\n        and sender_id=v_user_id\\n        and deleted_at is null;\\n      if not found then raise exception 'MESSAGE_NOT_FOUND'; end if;\\n      return jsonb_build_object('message_id',(p_input->>'message_id')::uuid,'deleted',true);\\n\\n    when 'testagram.messages.mark_read' then\\n      update public.conversation_members cm\\n      set last_read_at=greatest(coalesce(cm.last_read_at,'epoch'::timestamptz),m.created_at)\\n      from public.messages m\\n      where m.id=(p_input->>'message_id')::uuid\\n        and cm.conversation_id=m.conversation_id\\n        and cm.user_id=v_user_id\\n        and cm.left_at is null;\\n      return jsonb_build_object('message_id',(p_input->>'message_id')::uuid,'read',true);\\n\\n    when 'testagram.messages.react' then\\n      if coalesce((p_input->>'remove')::boolean,false) then\\n        delete from public.message_reactions\\n        where message_id=(p_input->>'message_id')::uuid\\n          and user_id=v_user_id\\n          and emoji=coalesce(nullif(p_input->>'reaction',''),'❤️');\\n        return jsonb_build_object('message_id',(p_input->>'message_id')::uuid,'reaction',coalesce(nullif(p_input->>'reaction',''),'❤️'),'removed',true);\\n      end if;\\n      insert into public.message_reactions(message_id,user_id,emoji)\\n      values((p_input->>'message_id')::uuid,v_user_id,coalesce(nullif(p_input->>'reaction',''),'❤️'))\\n      on conflict(message_id,user_id) do update set emoji=excluded.emoji;\\n      return jsonb_build_object('message_id',(p_input->>'message_id')::uuid,'reaction',coalesce(nullif(p_input->>'reaction',''),'❤️'),'removed',false);\\n\\n    when 'testagram.calls.create' then\\n      if not exists (\\n        select 1 from public.conversation_members cm\\n        where cm.conversation_id=(p_input->>'conversation_id')::uuid\\n          and cm.user_id=v_user_id and cm.left_at is null\\n      ) then\\n        raise exception using errcode='42501',message='Conversation membership required';\\n      end if;\\n      insert into public.calls(conversation_id,created_by,provider,room_name,kind,status,metadata)\\n      values(\\n        (p_input->>'conversation_id')::uuid,v_user_id,'livekit',\\n        coalesce(nullif(p_input->>'room_name',''),'testagram-'||replace(gen_random_uuid()::text,'-','')),\\n        coalesce(nullif(p_input->>'kind',''),'video'),'ringing',\\n        jsonb_build_object(\\n          'e2ee_enabled',true,\\n          'e2ee_epoch',coalesce((p_input->>'e2ee_epoch')::int,1)\\n        )\\n      )\\n      returning id into v_id;\\n      insert into public.call_participants(call_id,user_id,joined_at)\\n      values(v_id,v_user_id,now())\\n      on conflict(call_id,user_id) do nothing;\\n      return jsonb_build_object(\\n        'call_id',v_id,'provider','livekit',\\n        'room_name',(select room_name from public.calls where id=v_id),\\n        'kind',(select kind from public.calls where id=v_id),\\n        'created_by',v_user_id,'status','ringing',\\n        'conversation_id',(p_input->>'conversation_id')::uuid\\n      );\\n\\n    when 'testagram.calls.join' then\\n      update public.calls c\\n      set status=case when c.status='ringing' then 'active' else c.status end,\\n          started_at=coalesce(c.started_at,now())\\n      where c.id=(p_input->>'call_id')::uuid\\n        and c.status<>'ended'\\n        and exists(\\n          select 1 from public.conversation_members cm\\n          where cm.conversation_id=c.conversation_id\\n            and cm.user_id=v_user_id and cm.left_at is null\\n        );\\n      if not found then raise exception 'CALL_NOT_AVAILABLE'; end if;\\n\\n      insert into public.call_participants(call_id,user_id,joined_at)\\n      values((p_input->>'call_id')::uuid,v_user_id,now())\\n      on conflict(call_id,user_id) do update set joined_at=excluded.joined_at,left_at=null;\\n\\n      return jsonb_build_object('call_id',(p_input->>'call_id')::uuid,'joined',true);\\n\\n    when 'testagram.calls.end' then\\n      update public.calls c\\n      set status='ended', ended_at=coalesce(c.ended_at,now())\\n      where c.id=(p_input->>'call_id')::uuid\\n        and (\\n          c.created_by=v_user_id\\n          or exists(select 1 from public.call_participants cp where cp.call_id=c.id and cp.user_id=v_user_id)\\n        )\\n        and exists(\\n          select 1 from public.conversation_members cm\\n          where cm.conversation_id=c.conversation_id and cm.user_id=v_user_id and cm.left_at is null\\n        );\\n      if not found then raise exception 'CALL_NOT_FOUND'; end if;\\n\\n      update public.call_participants\\n      set left_at=coalesce(left_at,now())\\n      where call_id=(p_input->>'call_id')::uuid and user_id=v_user_id;\\n\\n      return jsonb_build_object('call_id',(p_input->>'call_id')::uuid,'ended',true);\\n\\n    else\\n      return public.capability_dispatch_legacy(p_capability,p_input);\\n  end case;\\nend;\\n$function$\\n
